"""Retained-tier acceptance and work/launch evidence for stable spatial softmax."""
import json,hashlib
import torch
from .weights import ROOT

def main():
 root=ROOT/'artifacts/video_runtime_v1/group_softmax_v1';video=root/'video';rows=[]
 module=json.loads((ROOT/'artifacts/video_runtime_v1/grouping_dataflow_v1/spatial/result.json').read_text());isolated=json.loads((root/'isolated.json').read_text())
 for tier in ('base','intersection','step'):
  old=json.loads((video/(tier+'_old')/'result.json').read_text());new=json.loads((video/(tier+'_new')/'result.json').read_text())
  ref=torch.load(video/(tier+'_old')/'latents.pt',weights_only=True);got=torch.load(video/(tier+'_new')/'latents.pt',weights_only=True)
  audit=json.loads((root/(tier+'_order_audit.json')).read_text());assert audit['events']==261 and audit['changed']==0
  rows.append(dict(tier=tier,old_seconds=old['median_seconds'],new_seconds=new['median_seconds'],speedup=old['median_seconds']/new['median_seconds'],old_clean_ms=old['stages']['clean_commit']['milliseconds'],new_clean_ms=new['stages']['clean_commit']['milliseconds'],latent_equal=torch.equal(ref,got),max_abs=float((ref.float()-got.float()).abs().max()),old_counters=old['runtime_stats']['counters'],new_counters=new['runtime_stats']['counters'],audit_events=audit['events']))
 assert all(r['latent_equal'] and r['old_counters']==r['new_counters'] for r in rows)
 (root/'acceptance.json').write_text(json.dumps(rows,indent=2)+'\n')
 lines=['# 保持FP32归约顺序的分组softmax优化','','## 验收结论','','基线为上一轮已经启用grouping_dataflow的三档，连续维softmax始终关闭。本轮只改变softmax线程与CTA分配，保留原FP32算术顺序。city_walk_s701，9chunks/105帧，768×512，history360/tile72。各档在同一GPU比较，完整预热后5次生成取中位数；不含VAE/IO，另做阶段插桩。','','| 档位 | 基线生成/s | 优化生成/s | 加速比 | clean commit/ms（前→后） | latent逐位一致 |','|---|---:|---:|---:|---:|---|']
 for r in rows:lines.append(f"| {r['tier']} | {r['old_seconds']:.5f} | {r['new_seconds']:.5f} | {r['speedup']:.4f}× | {r['old_clean_ms']:.2f}→{r['new_clean_ms']:.2f} | {r['latent_equal']} |")
 lines+=['','三档latent和运行计数均一致，783个clean事件的相同输入K/V与排序输出逐位一致。没有改权重、推理预算或分组规则。此次未重新做Dense质量比较，也未运行15s/30s视频。','', '## 为什么选择这个热点','','上一轮新profile发现非连续维softmax约0.50ms，占clean分组约20%。PyTorch 2.6对[12,1,4608,32]、dim=-2发射grid=[12,1,1]、block=[32,32,1]，仅12个CTA。上一轮转连续维的版本虽更快，却改变归约顺序，基础/step档产生视频轨迹差；本轮不采用那条路径。','', '## 算术不变，重新分配线程','','核对安装版本2.6.0+cu124对应提交2236df1770800ffea5697b11b0bb0d910b2e59e1的[SoftMax.cu](https://github.com/pytorch/pytorch/blob/2236df1770800ffea5697b11b0bb0d910b2e59e1/aten/src/ATen/native/cuda/SoftMax.cu)。每列32个线程按lane,lane+32,…读取；最大值和指数和按offset16,8,4,2,1归约。保留expf、FP32除法与输入输出布局，不使用fast-math。','', '先实现原32列CTA控制，确认与PyTorch逐位相同；再将每CTA改为4列，得到96CTA；最后把线程排列为block=[4,32,1]，邻近线程优先处理邻近列。没有扩大参数搜索。','', '| softmax路径 | 中位数/ms |','|---|---:|']
 for name,value in isolated['medians_ms'].items():lines.append(f'| {name} | {value:.6f} |')
 lines+=['',f"最终softmax加速{isolated['speedup']:.3f}×。完整分组包含输入复制、权重刷新、排序与K/V重排，{module['medians']['old']['gpu_ms']:.4f}→{module['medians']['new']['gpu_ms']:.4f}ms，{module['speedup']:.4f}×。不能把softmax加速比当作完整视频加速比。",'', '## profile及理论工作量','','同一轮模块profile：原softmax495.864us，新103.124us。grid从[12,1,1]到[12,8,1]；block从[32,32,1]到[4,32,1]；寄存器26→20/thread，共享内存4096→512B/CTA。两版总warp数均384，估计整体occupancy仍约6%；改进是CTA覆盖更多SM以及访存布局，不能写成总occupancy提高8倍。','', '共1,769,472个FP32元素。每元素在max、sum、输出三阶段各读一次并写一次，逻辑流量约28.312MB，算法工作量未减少；输入约7.078MB，可被L2复用，所以不能把逻辑流量全算成HBM。以既有1266.396GB/s复制参考换算0.0224ms；新0.108ms仍约4.8倍，但其中包含指数、逐线程串行累加、同步和归约，不能视为都能收回的空间。','', '完整分组每次节省约0.39ms，261次clean commit约102ms，视频收益应在这一量级。层内QKV/FFN、Attention和路由未改，不预期同比例缩短。','', '## 数值与边界','','15组单模块对照：真实score、随机值、大尺度、常量、小尺度输入，各比较原布局控制、4列CTA、4列合并访存；全部逐位一致。完整分组四组原输入/移位输入/权重更新同样一致。三档各261个clean输入审计和三档完整短视频已覆盖原连续softmax出现排序变化的事件。','', '该核专门用于连续FP32、最后维32的clean分组score，保留32线程归约，目标设备为本机A100。NVCC以-O3、sm_80编译到快速/tmp缓存，不启用--use_fast_math。源码SHA进入部署identity，基准快照包含.cu；首次编译发生在warmup。每GPU一个worker的现有执行方式不变。','', '## 代码与记录','','- [CUDA核](../../../local_experiments/video_runtime_v1/csrc/group_softmax.cu)：相同顺序的空间softmax、4列CTA和线程重排。','- [加载与调用](../../../local_experiments/video_runtime_v1/group_softmax.py)：源码哈希缓存、文件锁、当前CUDA stream调用。','- [分组接入](../../../local_experiments/video_runtime_v1/grouping_dataflow.py)、[部署](../../../local_experiments/video_runtime_v1/deployment.py)。','- [单模块测试](../../../local_experiments/video_runtime_v1/check_group_softmax.py)、[同输入审计](../../../local_experiments/video_runtime_v1/audit_group_softmax.py)。','- [模块结果](isolated.json)、[视频结果](acceptance.json)、[base审计](base_order_audit.json)、[intersection审计](intersection_order_audit.json)、[step审计](step_order_audit.json)。','', '三档入口`accepted_tiers`的`--grouping-spatial`启用本轮路径；连续布局`--grouping-softmax`仍为独立实验开关。']
 lines+=['', '## 默认接入与下一轮profile', '', 'grouping_spatial已默认启用，benchmark/worker/三档入口共享配置；`--no-grouping-spatial`复现上一轮dataflow基线。实验连续布局须显式`--no-grouping-spatial --grouping-softmax`，不允许同时启用。实测编译工具为NVCC12.2.128；PyTorch版本为2.6.0+cu124。', '', '默认路径再次profile保存于accepted_profile。满窗口精算0.7634ms/层，补偿0.4421ms/层；新的分组softmax0.1079ms。精算每页QK一次、AV高低项两次，43页时Tensor Core主算术约116.87GFLOPs（必须计入额外AV项），约153.1TFLOP/s，相对既有大BF16 GEMM参考202.1TFLOP/s约76%。它虽耗时较长，却已兑现相当部分参考吞吐。', '', '补偿包括全部1728代表QK、完整128维mean的两项AV、三个detail的两项AV（物理宽16），主算术约41.28GFLOPs，约93.4TFLOP/s，为同参考约46%；还包含softmax/权重归约/在线缩放。_tail报告255寄存器/thread、56,832B共享内存/CTA，值得下一轮优先查中间量生命周期与重复计算，而不是先重复精算block/warp搜索。大GEMM参考不能承诺这些非线性与归约都消失。profile的部分旧Triton occupancy字段为0，不把该字段当实际占用率。']
 (root/'MODULE_DISTANCE.zh.md').write_text('\n'.join(lines)+'\n');print(json.dumps(rows,indent=2))
if __name__=='__main__':main()
